      "evidence": [
        "ae_death_by_year.csv shows sustained YoY rise 1.025->1.100->1.111->1.149; drops to ~0.95-0.99 from 2020 (settling ~0.08 below baseline); empirical SD 1.4x Poisson (approx valid)"
      ],
      "recommended_action": "Investigate drivers of 2016-2019 elevation (e.g., adverse selection, reporting lags); monitor if post-2020 lower level persists; reassess pricing/valuation assumptions if structural"
    },
    {
      "benefit": "TPD",
      "years": [2019, 2021],
      "pattern": "drift",
      "direction": "increase",
      "magnitude": "~+0.25 A/E (1.020 to 1.221)",
      "confidence": 0.90,
      "evidence": [
        "ae_tpd_by_year.csv shows YoY rise 1.020->1.221->1.187; reverts to ~0.94 from 2022; empirical SD 3.3x Poisson but consistent with isolated period rather than persistent volatility"
      ],
      "recommended_action": "Review 2019-2021 drivers (e.g., external shocks, severity shifts); confirm reversion stability; adjust duration/termination assumptions if needed"
    }
  ]
}

